class Loan {
    public double calculateEMI(double principal) {
        double simpleInterest = (principal * 8.5 * 5) / 100;
        return (simpleInterest + principal) / 5;
    }
}

class HomeLoan extends Loan {
    public double calculateEMI(double principal) {
        int additionalTax = 200;
        // Call parent class method using super
        double emi = super.calculateEMI(principal);
        return emi + additionalTax;
    }
}

class ExecuteLoan {
    public static void main(String[] args) {
        Loan loan = new HomeLoan();  // Runtime polymorphism
        double hloan = loan.calculateEMI(2000000);
        System.out.println("Home loan emi per year... " + hloan);
    }
}

class Loan {
    Loan() {
        System.out.println("Loan constructor");
    }
}

class HomeLoan extends Loan {
    HomeLoan() {
        super(); // must be first statement
        System.out.println("HomeLoan constructor");
    }
}

class ExecuteLoan {
    public static void main(String[] args) {
        HomeLoan h = new HomeLoan();
    }
}

class Loan {
    int rate = 8;
}

class HomeLoan extends Loan {
    int rate = 10;

    void printRates() {
        System.out.println("Child rate: " + rate);
        System.out.println("Parent rate: " + super.rate);
    }
}

class ExecuteLoan {
    public static void main(String[] args) {
        HomeLoan h = new HomeLoan();
        h.printRates();
    }
}

